local UICommonMessageBarView = BaseClass("UICommonMessageBarView",UIBaseView)
local base = UIBaseView

local CommonMessageBarItem = require "UI.UICommonMessageBar.View.CommonMessageBarItem"

local closeBtn_path = "Panel"
local messageItem_path = "Panel/msgItem"

local timeBeforeFadeOut = 1
local defaultposy = -9999
local defaultposx = -9999
function UICommonMessageBarView:OnCreate()
    base.OnCreate(self)
    
    self.closeBtnN = self:AddComponent(UIButton, closeBtn_path)
    self.closeBtnN:SetOnClick(function()  
        self.ctrl:CloseSelf()
    end)
    if defaultposy == -9999 then
        local vec2 = self.closeBtnN:GetAnchoredPosition()
        defaultposx,defaultposy = vec2.x,vec2.y
    end
    self.messageItems = {}
    for i = 1, 2 do
        local tempItem = self:AddComponent(CommonMessageBarItem, messageItem_path .. i)
        table.insert(self.messageItems, tempItem)
    end

    self.isReady = true
    self.displayTime = 0
    self.inUseItems = self.messageItems--暂时没用
    self.outUseItems = {}--暂时没用
    self.displayingIndex = 0
    self:TryDisplayNext()
end

function UICommonMessageBarView:OnDestroy()
    if self.messageItems~=nil then
        for i, v in ipairs(self.messageItems) do
            v:ResetItem()
        end
    end
    self.tmppos = 0
    self:ResetPanelPos()
    self.closeBtnN = nil
    self.messageItems = nil
    self.msgQueue = nil

    self:DeleteTimer()
    base.OnDestroy(self)
end

function UICommonMessageBarView:OnEnable()
    base.OnEnable(self)
    self.isReady = true
end

function UICommonMessageBarView:OnDisable()
    base.OnDisable(self)
end

function UICommonMessageBarView:ResetPanelPos()
    if self.closeBtnN then
        self.closeBtnN:SetAnchoredPositionXY(defaultposx,defaultposy)
    end
end

function UICommonMessageBarView:SetPanelPosCaches(offsetx,offsety)
    self.tmpposy = offsety
end

function UICommonMessageBarView:SetPanelPos(offsetx,offsety)
    if self.closeBtnN then
        self.closeBtnN:SetAnchoredPositionXY(defaultposx+offsetx,defaultposy+offsety)
    end
end

--新提示
--playerHead = {uid = "", pic = "", picVer = ""}
function UICommonMessageBarView:AddNewMsg(newMsg, showTime)
    if not self.msgQueue then
        self.msgQueue = {}
    end
    if self.msgQueue == nil then
        self.msgQueue = {}
    end
    if showTime ~= nil then
        self.showEndTime = tonumber(showTime)
    end
    if showTime == nil or self.showEndTime == 0 then
        self.showEndTime = 2
    end
    table.insert(self.msgQueue, newMsg)
    if not self.timer then
        self:TryDisplayNext()
        self.timer = TimerManager:GetInstance():GetTimer(timeBeforeFadeOut, self.TimerAction , self, false,false,false)
        self.timer:Start()
    end
    if self.timer and (not self.timer.started or self.timer.over) then--self.isReady then
        self.timer:Reset()
    end
end

