function UICommonMessageBarView:TryDisplayNext()
    if self.isReady then
        if self.msgQueue and #self.msgQueue > 0 then
            local freeItem, freeIndex = self:GetOneFreeItem()
            local nextMsg = self:GetNextMsg()
            freeItem:ResetItem()
            freeItem:FadeIn(nextMsg, self.showEndTime)
            self.displayTime = 0

            local displayingItem = self:GetDisplayingItem()
            if displayingItem then
                displayingItem:FadeOut(true)
            end
            self.displayingIndex = freeIndex 
            self.isReady = false
        else
            if self.displayTime >= self.showEndTime then
                self.ctrl:CloseSelf()
            end
        end
        if self.tmpposy == nil then
            self.tmpposy = 0
        end
        self:SetPanelPos(0,self.tmpposy)
    end
end

function UICommonMessageBarView:GetNextMsg()
    if self.msgQueue and #self.msgQueue > 0 then
        local msg = self.msgQueue[1]
        table.remove(self.msgQueue, 1)
        if msg then
            return msg
        end
    end
end

function UICommonMessageBarView:Clear()
    self.msgQueue = nil
    self:DeleteTimer()
end

function UICommonMessageBarView:TimerAction()
    if self.displayTime == nil then
        return
    end
    self.isReady = true
    self.displayTime = self.displayTime + timeBeforeFadeOut
    self:TryDisplayNext()
end

function UICommonMessageBarView:DeleteTimer()
    if self.timer ~= nil then
        self.timer:Stop()
        self.timer = nil
    end
end

--临时只有两个，可扩展支持同时显示多个
function UICommonMessageBarView:GetOneFreeItem()
    if self.displayingIndex ~= 1 then
        return self.messageItems[1], 1
    else
        return self.messageItems[2], 2
    end
end

function UICommonMessageBarView:GetDisplayingItem()
    if self.displayingIndex ~= 0 then
        return self.messageItems[self.displayingIndex]
    else
        return nil
    end
end

function UICommonMessageBarView:OnAddListener()
    base.OnAddListener(self)
    self:AddUIListener(EventId.LoadingState, self.OnLoginState)
end

function UICommonMessageBarView:OnRemoveListener()
    base.OnRemoveListener(self)
    self:RemoveUIListener(EventId.LoadingState, self.OnLoginState)
end
--LuaEntry里面会把所有timer都清掉，这个地方做个容错处理
function UICommonMessageBarView:OnLoginState(state)
    -- 10 = LoadingState.EnterGame。barrel 里这个枚举在 Loading/Const.lua，
    -- 本框架没有该文件，AppStartupLoading.lua:17 的 LoadingState 是 local 表、外部取不到，
    -- 故直接用字面量。改动 AppStartupLoading 的枚举值时需同步这里。
    if state == 10 then
        self.ctrl:CloseSelf()
    end
end

return UICommonMessageBarView